import{_ as t,a as r,c as a,ac as i}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"易经：古籍书目、图源与整理说明","description":"记录本专题实际查阅的经传、注疏和图学资料，区分公有领域古文、本站概括和历史图像，并说明电子本的校核限制。","frontmatter":{"title":"易经：古籍书目、图源与整理说明","description":"记录本专题实际查阅的经传、注疏和图学资料，区分公有领域古文、本站概括和历史图像，并说明电子本的校核限制。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"记录本专题实际查阅的经传、注疏和图学资料，区分公有领域古文、本站概括和历史图像，并说明电子本的校核限制。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"易经：术语、读音与常见误解","link":"/life/personal/yijing/glossary"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"易经：术语、读音与常见误解","link":"/life/personal/yijing/glossary"},"next":false},"headers":[],"relativePath":"life/personal/yijing/bibliography.md","filePath":"life/personal/yijing/bibliography.md"}'),n={name:"life/personal/yijing/bibliography.md"};function o(d,e,l,s,h,g){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="易经-古籍书目、图源与整理说明" tabindex="-1">易经：古籍书目、图源与整理说明 <a class="header-anchor" href="#易经-古籍书目、图源与整理说明" aria-label="Permalink to &quot;易经：古籍书目、图源与整理说明&quot;">​</a></h1><p>本专题以公开可查的古籍电子文本为入口，再作简体说明、分层比较和学习练习。来源核对日期为 <strong>2026-10-22</strong>。核对日期只表示这次查阅，不表示古籍、电子文本或图片的创作日期。</p><h2 id="主要古籍" tabindex="-1">主要古籍 <a class="header-anchor" href="#主要古籍" aria-label="Permalink to &quot;主要古籍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文献</th><th>本次使用的位置</th><th>用途</th></tr></thead><tbody><tr><td><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93" target="_blank" rel="noopener noreferrer">《周易》</a></td><td>六十四卦各篇及上下卦表</td><td>核对卦名、篇次、卦爻辞与传文；每卦页有具体链接</td></tr><tr><td><a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3" target="_blank" rel="noopener noreferrer">《易传》</a></td><td>七种十篇</td><td>区分经传层次，理解彖象、系辞、文言、说卦、序卦、杂卦</td></tr><tr><td><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9" target="_blank" rel="noopener noreferrer">《周易正义》</a></td><td>各卦经文、王弼等注与孔颖达疏</td><td>交叉核对字句，并与现代解释区分</td></tr><tr><td><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%B3%A8%E7%96%8F_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD" target="_blank" rel="noopener noreferrer">《周易注疏》四库本全览</a></td><td>提要、序及相关注疏</td><td>了解注疏传统、古注的概念与解释方法</td></tr><tr><td><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E7%95%A5%E4%BE%8B/%E6%98%8E%E5%BD%96" target="_blank" rel="noopener noreferrer">《周易略例·明彖》</a></td><td>统论一卦与主旨</td><td>理解王弼的整体阅读方法</td></tr><tr><td><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E7%95%A5%E4%BE%8B/%E6%98%8E%E8%B1%A1" target="_blank" rel="noopener noreferrer">《周易略例·明象》</a></td><td>言、象、意及取象批评</td><td>避免机械配象，说明注家之间的方法分歧</td></tr><tr><td><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%9C%AC%E7%BE%A9_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD" target="_blank" rel="noopener noreferrer">《周易本义》四库本全览</a></td><td>提要、图目、卦歌与相关注释</td><td>了解经传编排、先后天图式及朱熹一系的解释</td></tr><tr><td><a href="https://zh.wikisource.org/wiki/%E4%BC%8A%E5%B7%9D%E6%98%93%E5%82%B3" target="_blank" rel="noopener noreferrer">《伊川易传》</a></td><td>卷一乾卦相关注释</td><td>与王弼、孔颖达、朱熹比较元亨利贞、德位和时义</td></tr><tr><td><a href="https://www.shidianguji.com/book/SK0061/chapter/1l9qr24ok8562" target="_blank" rel="noopener noreferrer">《易学启蒙通释·考变占》</a></td><td>所录《启蒙》变占条文与解释</td><td>核对多动爻取辞，并区分原条文、推例和教学简化</td></tr><tr><td><a href="https://zh.wikisource.org/wiki/%E4%BA%AC%E6%B0%8F%E6%98%93%E5%82%B3_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD" target="_blank" rel="noopener noreferrer">《京氏易传》四库本全览</a></td><td>提要、乾宫及相关条文</td><td>识别八宫、纳甲、世应等后世体系的边界</td></tr><tr><td><a href="https://zh.wikisource.org/wiki/%E6%A2%85%E8%8A%B1%E6%98%93%E6%95%B8" target="_blank" rel="noopener noreferrer">《梅花易数》</a></td><td>序与卷目</td><td>确认传本所含的方法与术语，不据传说故事认定史实</td></tr><tr><td><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E5%8F%83%E5%90%8C%E5%A5%91" target="_blank" rel="noopener noreferrer">《周易参同契》</a></td><td>书目与篇章目录</td><td>标示借用易学语汇的其他著作，不作丹法或医疗指导</td></tr></tbody></table><p>历代注家、筮仪与变占规则的更具体出处见<a href="./commentaries">注家比较</a>、<a href="./divination">筮法</a>各节。这里的列表说明实际使用范围，不声称对每部书做过逐字通校。中国哲学书电子化计划可作扩展检索入口，但本次部分页面返回访问限制，因此没有把未读到的页面当作已核实的引用依据。</p><h2 id="哪些内容是古文-哪些是本站整理" tabindex="-1">哪些内容是古文，哪些是本站整理 <a class="header-anchor" href="#哪些内容是古文-哪些是本站整理" aria-label="Permalink to &quot;哪些内容是古文，哪些是本站整理&quot;">​</a></h2><ul><li><strong>古籍原文</strong>：卦辞、爻辞、彖象等明确标注的引文，保留原书语境；古代作者的文字属于公有领域材料。</li><li><strong>古注概括</strong>：标明王弼、孔颖达、程颐、朱熹等名字时，是对相应古注的概括，不表示所有注家都同意。</li><li><strong>本站白话与练习</strong>：各节导读、解释、比较、表格和练习为本次整理；不是现代出版译注的复制，也不自称唯一标准译文。</li><li><strong>现代类比</strong>：为帮助学习而提出，应能与原文、传统解释分别识别，不冒充古代作者的原话。</li></ul><p>电子平台的页面编排、现代译注、图片授权各有具体条款，不能因为古书原文古老，就把整张网页上的所有内容都视为无条件可复制。本站使用古籍原文并保留链接，不转载现代译注全文。</p><h2 id="版本、异文与断句" tabindex="-1">版本、异文与断句 <a class="header-anchor" href="#版本、异文与断句" aria-label="Permalink to &quot;版本、异文与断句&quot;">​</a></h2><p>《周易》的传世本、注疏本和出土材料并非处处相同，古人断句与今人标点也可能影响理解。电子文本还可能包含漏字、转写错误或把校注混入正文的情况。本专题六十四卦以通行经文和《周易正义》对照，遇到影响理解的异文另行提示。</p><p>正文讲解使用简体中文，古文引用多保留繁体与“无”等常见古籍写法。个别异体可用通行字显示，但不据简繁转换解决训诂问题。引文中的现代标点用于阅读，不意味着原始简帛已有这些标点。</p><p>如需学术引用，应进一步检查所用底本、卷次、页码和影印图；本站网页及电子本可以提供线索，不能替代校勘版本。</p><h2 id="图片来源与本地文件" tabindex="-1">图片来源与本地文件 <a class="header-anchor" href="#图片来源与本地文件" aria-label="Permalink to &quot;图片来源与本地文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本地文件</th><th>性质</th><th>来源或绘制依据</th></tr></thead><tbody><tr><td><a href="/life/yijing/leibniz-hexagrams-1701.jpg">leibniz-hexagrams-1701.jpg</a></td><td>历史原图，未修改</td><td><a href="https://commons.wikimedia.org/wiki/File:Diagram_of_I_Ching_hexagrams_owned_by_Gottfried_Wilhelm_Leibniz,_1701.jpg" target="_blank" rel="noopener noreferrer">Commons 资源页</a>；PD-Art／Public Domain Mark 1.0；原图作者不详，资源页说明数字由莱布尼茨添写</td></tr><tr><td><a href="/life/yijing/trigrams.svg">trigrams.svg</a></td><td>本站今绘</td><td>《说卦》及通行八卦图形；数字从下向上记爻</td></tr><tr><td><a href="/life/yijing/line-positions.svg">line-positions.svg</a></td><td>本站今绘</td><td>《周易·既济》的六爻与上下卦</td></tr><tr><td><a href="/life/yijing/bagua-orders.svg">bagua-orders.svg</a></td><td>本站今绘</td><td>《说卦》《周易本义》所见传统图式；统一南上北下</td></tr><tr><td><a href="/life/yijing/hetu-luoshu.svg">hetu-luoshu.svg</a></td><td>本站今绘</td><td>朱熹一系通行河图洛书数位；用数字代替黑白点</td></tr><tr><td><a href="/life/yijing/hexagrams.svg">hexagrams.svg</a></td><td>本站今绘</td><td>《周易》通行卦序与上下卦组合</td></tr></tbody></table><p>历史原图的公开领域标记可核对<a href="https://creativecommons.org/publicdomain/mark/1.0/" target="_blank" rel="noopener noreferrer">Public Domain Mark 1.0</a>。图像的原始文件 URL、字节数、SHA-256 和核对日期保存在项目的 <code>content/yijing-assets.json</code>；本地资源目录为 <code>docs/public/life/yijing/</code>。示意图可由 <code>node scripts/yijing-assets.mjs</code> 重新生成，历史原图不会由脚本改写。</p><h2 id="本专题的范围" tabindex="-1">本专题的范围 <a class="header-anchor" href="#本专题的范围" aria-label="Permalink to &quot;本专题的范围&quot;">​</a></h2><p>已整理六十四卦的卦辞、六爻及乾坤用九用六，并配大象、读法和来源；十翼与古注提供专题导读，未把历代全部注疏原样收进本站。出土文本、训诂争议、各家卦变与后世术数需要更细的专门研究，相关页面会明确说明层次和限制。</p><p>继续扩充时，应保留相同原则：先读原书，再写总结；一句话能定位到具体篇章；史实与传统题署分开；图片有出处且在本地可用；不为了增加篇幅重复套用空泛的处世建议。</p><p><a href="./overview">返回易经专题导读</a></p>',19)])])}const f=t(n,[["render",o]]);export{c as __pageData,f as default};
